import { SwimlaneElement, css, html } from '@swimlane/swimlane-element@2';
import { recordFrameTemplate } from '@swimlane/swimlane-element@2/lib/templates.js';

import 'https://widgets.swimlane.app/swim-ui/1/swim-ui.js';

/**
 * Widget configuration (merge via setConfig from the layout editor or hosting app).
 *
 * Store dropdown choices on your custom asset under `params`, e.g. params.dropdownOptions = [...]
 * A scheduled playbook can refresh that structure so the next widget load sees new values.
 */
const config = {
  /** Exact asset `name` (same pattern as other widgets that locate assets by name). */
  assetName: 'AI_SOC_Clients_List',
  /**
   * Dot-path under `asset.params` to an array of options.
   * Example: `dropdownOptions` or `lists.categories`.
   */
  optionsPath: 'Client_List',
  /** Knowledge base / record field key to receive the selected value (string-friendly field recommended). */
  targetField: 'client-name',
  label: 'Client name',
  placeholder: 'Select',
  /**
   * Persist after selection on existing records. On **new** articles, see
   * `triggerSaveOnChangeWhenNew` (default false) so required fields can be filled first.
   */
  triggerSaveOnChange: false,
  /** If true, calls triggerSave() when the user picks a value on a new (unsaved) article. */
  triggerSaveOnChangeWhenNew: false,
  /** Page size for asset RQL when resolving `assetName`. */
  assetRqlLimit: 200
};

function getContext(el) {
  let ctx =
    el?.['context-data'] ||
    el?.contextData ||
    (typeof window !== 'undefined' ? window?.swimlane?.contextData : null) ||
    el?.record?.contextData ||
    {};

  if (!ctx.origin && typeof window !== 'undefined' && window.location?.origin) {
    ctx = { ...ctx, origin: window.location.origin };
  }
  return ctx;
}

/** True when the user is on the create-article form (no persisted record id yet). */
function isNewRecord(record) {
  if (!record) {
    return false;
  }
  if (record.isNew === true || record.isHangfireCreatedAndUnpersisted === true) {
    return true;
  }
  return !record.id;
}

function orchestrationBase(ctx) {
  const { origin, tenantPath: tp, accountId, tenantId } = ctx;
  let tenantPath = tp;
  if (!tenantPath && accountId && tenantId) {
    tenantPath = `account/${accountId}/tenant/${tenantId}/`;
  }
  if (!origin || !tenantPath) {
    return null;
  }
  return `${origin}/orchestration/api/${tenantPath}`;
}

function getAt(obj, path) {
  if (obj == null || !path) {
    return obj;
  }
  return path.split('.').reduce((acc, key) => (acc == null ? acc : acc[key]), obj);
}

function normalizeOptions(raw) {
  if (!Array.isArray(raw)) {
    return [];
  }
  const out = [];
  for (const entry of raw) {
    if (entry == null) {
      continue;
    }
    if (typeof entry === 'string' || typeof entry === 'number' || typeof entry === 'boolean') {
      const v = entry;
      const s = String(v);
      out.push({ name: s, value: v });
      continue;
    }
    if (typeof entry === 'object') {
      const value =
        entry.value !== undefined
          ? entry.value
          : entry.id !== undefined
            ? entry.id
            : entry.key !== undefined
              ? entry.key
              : null;
      const name =
        entry.name ??
        entry.label ??
        entry.title ??
        (value !== null ? String(value) : '');
      if (value === null && name === '') {
        continue;
      }
      out.push({
        name: name !== '' ? String(name) : String(value),
        value: value !== null ? value : String(name)
      });
    }
  }
  return out;
}

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function readScalarField(record, fieldKey) {
  if (!record || !fieldKey) {
    return null;
  }
  let raw = Object.prototype.hasOwnProperty.call(record, fieldKey) ? record[fieldKey] : undefined;
  if (raw == null && record.values && Object.prototype.hasOwnProperty.call(record.values, fieldKey)) {
    raw = record.values[fieldKey];
  }
  if (raw == null) {
    return null;
  }
  if (typeof raw === 'object' && raw !== null && 'value' in raw) {
    return raw.value;
  }
  return raw;
}

export default class KbAssetDropdown extends SwimlaneElement {
  static get properties() {
    return {
      _options: { type: Array },
      _loadState: { type: String },
      _error: { type: String }
    };
  }

  static get styles() {
    return [
      super.styles,
      css`
        .frame::after {
          content: 'Organization Name';
        }
        .kb-asset-dd {
          padding: 16px;
          display: flex;
          flex-direction: column;
          gap: 8px;
          min-width: 200px;
        }
        .hint {
          font-size: 13px;
          color: var(--color-text-secondary, #6c757d);
        }
        .err {
          font-size: 13px;
          color: var(--color-danger, #ff4514);
        }
      `
    ];
  }

  constructor() {
    super();
    this.setConfig(config);
    this._options = [];
    this._loadState = 'idle';
    this._error = '';
    this._assetsLoadStarted = false;
    this._draftSelection = null;
  }

  setConfig(config, replaceAll = false) {
    this.config = replaceAll ? config : { ...this.config, ...config };
  }

  connectedCallback() {
    super.connectedCallback();
    this._tryLoadAssetOptions();
  }

  _hasOrchestrationContext() {
    return orchestrationBase(getContext(this)) != null;
  }

  _tryLoadAssetOptions() {
    if (this._assetsLoadStarted || !this._hasOrchestrationContext()) {
      return;
    }
    if (!(this.config.assetName || '').trim()) {
      return;
    }
    this._assetsLoadStarted = true;
    this._loadAssetOptions();
  }

  updated(changed) {
    super.updated(changed);
    if (changed.has('contextData') || changed.has('context-data')) {
      this._tryLoadAssetOptions();
    }
    if (changed.has('record') && this.config.targetField) {
      const fromRecord = readScalarField(this.record, this.config.targetField);
      if (fromRecord != null && fromRecord !== '') {
        this._draftSelection = fromRecord;
      }
      this.requestUpdate();
    }
  }

  _shouldTriggerSave() {
    const onChange = this.config.triggerSaveOnChange !== false;
    if (!onChange) {
      return false;
    }
    if (isNewRecord(this.record)) {
      return this.config.triggerSaveOnChangeWhenNew === true;
    }
    return true;
  }

  async _fetchJson(url, init) {
    const res = await fetch(url, {
      credentials: 'include',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      ...init
    });
    const text = await res.text();
    let body;
    try {
      body = text ? JSON.parse(text) : null;
    } catch {
      body = text;
    }
    if (!res.ok) {
      const msg = typeof body === 'object' && body && body.message ? body.message : text || res.statusText;
      throw new Error(msg || `HTTP ${res.status}`);
    }
    return body;
  }

  async _loadAssetOptions() {
    const base = orchestrationBase(getContext(this));
    const name = (this.config.assetName || '').trim();
    const optionsPath = (this.config.optionsPath || 'dropdownOptions').trim();

    if (!base) {
      this._loadState = 'idle';
      this._error = '';
      this._options = [];
      this._assetsLoadStarted = false;
      return;
    }
    if (!name) {
      this._loadState = 'error';
      this._error = 'Configure assetName in widget settings.';
      this._options = [];
      return;
    }

    this._loadState = 'loading';
    this._error = '';
    this.requestUpdate();

    try {
      const limit = Math.min(Math.max(Number(this.config.assetRqlLimit) || 200, 1), 500);
      const rqlUrl = `${base}v1/asset/rql`;
      const page = await this._fetchJson(rqlUrl, {
        method: 'POST',
        body: JSON.stringify({ rql: `limit(${limit})` })
      });

      const items = page?.items || [];
      let assetRow = null;
      for (const row of items) {
        const doc = row.item || row;
        if (doc?.name === name) {
          assetRow = doc;
          break;
        }
      }

      if (!assetRow?.id) {
        throw new Error(`No asset named "${name}" found in the first ${limit} results. Refine RQL or increase assetRqlLimit.`);
      }

      const asset = await this._fetchJson(`${base}v1/asset/${assetRow.id}`, { method: 'GET' });
      const params = asset?.params ?? {};
      let rawList = getAt(params, optionsPath);
      if (typeof rawList === 'string') {
        try {
          rawList = JSON.parse(rawList);
        } catch {
          /* single string option */
        }
      }
      this._options = normalizeOptions(rawList);
      this._loadState = 'ready';
    } catch (e) {
      console.error('[kb-asset-dropdown]', e);
      this._loadState = 'error';
      this._error = e?.message || String(e);
      this._options = [];
    }
  }

  async _onSelectChange(e) {
    const field = (this.config.targetField || '').trim();
    if (!field) {
      this.triggerNotification('error', 'Configuration', 'Set targetField in the widget configuration.');
      return;
    }

    const value = e.detail?.value;
    this._draftSelection = value;
    this.updateRecordValue(field, value);

    if (this._shouldTriggerSave()) {
      try {
        await delay(1000);
        await this.triggerSave();
        this.triggerNotification('success', 'Saved', 'Article saved.');
      } catch (err) {
        console.error('[kb-asset-dropdown] triggerSave', err);
        this.triggerNotification('error', 'Save failed', err?.message || String(err));
      }
    } else if (isNewRecord(this.record)) {
      this.triggerNotification(
        'info',
        'Selection applied',
        'Complete the article and use Save to create the KB record.'
      );
    }
  }

  render() {
    const field = (this.config.targetField || '').trim();
    const cfgErr = !field || !(this.config.assetName || '').trim();
    const selected =
      readScalarField(this.record, field) ?? (this._draftSelection != null ? this._draftSelection : null);
    const creating = isNewRecord(this.record);
    const waitingContext = !cfgErr && !this._hasOrchestrationContext();
    const disabled =
      this._loadState === 'loading' || cfgErr || this._loadState === 'error' || waitingContext;

    return recordFrameTemplate(html`
      <div class="kb-asset-dd">
        ${cfgErr
          ? html`<div class="err">Configure assetName and targetField (Knowledge Base field key).</div>`
          : null}
        ${waitingContext ? html`<div class="hint">Waiting for platform context…</div>` : null}
        ${this._error && !cfgErr && !waitingContext ? html`<div class="err">${this._error}</div>` : null}
        ${this._loadState === 'loading' ? html`<div class="hint">Loading options from asset…</div>` : null}
        ${creating && !cfgErr
          ? html`<div class="hint">New article: your choice is applied to the form and saved when you click Save.</div>`
          : null}
        <swim-select
          label=${this.config.label || ''}
          placeholder=${this.config.placeholder || 'Select...'}
          .options=${this._options}
          .value=${selected}
          ?disabled=${disabled}
          empty-placeholder="No options in asset params"
          @change=${this._onSelectChange}
        ></swim-select>
        ${this._loadState === 'ready' && this._options.length === 0 && !cfgErr
          ? html`<div class="hint">
              No options at params.${this.config.optionsPath || 'dropdownOptions'}. Ensure your scheduled job
              writes an array there.
            </div>`
          : null}
      </div>
    `);
  }
}

import ToggleSlider from 'https://widgets.swimlane.app/toggle-slider/3/index.js';

export default class extends ToggleSlider {
  constructor() {
    super();
    this.setConfig({
        title: 'Enabled',
        fieldKey: 'status',
        defaultValue: 'Disabled',
        nonDefaultValue: 'Enabled',
        triggerPlaybookOnChange: false,
        triggerSaveOnChange: false
    });
  }
}

